#include <string>
#include <vector>

struct Enemy { std::string name; int hp; };

std::vector<std::string> enemyWindow(const std::vector<Enemy>& enemies)
{
    std::vector<std::string> lines{ "" };
    int alive{ 0 };
    for (const Enemy& e : enemies)
    {
        if (e.hp <= 0) continue;
        ++alive;
        lines.push_back(e.name + " (" + std::to_string(e.hp) + " hp)");
    }
    lines[0] = "Enemies alive: " + std::to_string(alive);
    if (alive == 0) lines.push_back("(none)");
    return lines;
}

unitTests:
using Lines = std::vector<std::string>;
TEST("some alive") { CHECK_EQ(enemyWindow({ { "Bat", 5 }, { "Rat", 0 }, { "Slime", 12 } }), (Lines{ "Enemies alive: 2", "Bat (5 hp)", "Slime (12 hp)" })); }
TEST("none alive") { CHECK_EQ(enemyWindow({ { "Rat", 0 }, { "Bat", -3 } }), (Lines{ "Enemies alive: 0", "(none)" })); CHECK_EQ(enemyWindow({}), (Lines{ "Enemies alive: 0", "(none)" })); }
TEST("the next frame reflects the change") { std::vector<Enemy> e{ { "Bat", 5 } }; CHECK_EQ(enemyWindow(e).size(), std::size_t{ 2 }); e[0].hp = 0; CHECK_EQ(enemyWindow(e), (Lines{ "Enemies alive: 0", "(none)" })); }

